(() => {
  const ID = 'ping-pong-rush';
  const shell = () => window.TelePlayGameShell;
  const tg = window.Telegram?.WebApp;
  let screen, ball, hint, scoreEl, rallyEl, rally = 0, score = 0, target = 'left', running = false, paused = false, callbacks = {}, initialized = false, timer = 0;
  const $ = id => document.getElementById(id);
  const haptic = type => { try { tg?.HapticFeedback?.impactOccurred(type); } catch (_) {} };
  function nextBall() { target = Math.random() > .5 ? 'left' : 'right'; ball.style.left = target === 'left' ? '35%' : '65%'; ball.style.top = '39%'; hint.textContent = `Возвращай мяч: ${target === 'left' ? 'влево' : 'вправо'}`; }
  function hit(side) { if (!running || paused) return; if (side !== target) { finish(false); return; } rally += 1; score += 20 + rally * 5; scoreEl.textContent = score.toLocaleString('ru-RU'); rallyEl.textContent = `×${rally}`; ball.classList.remove('is-hit'); requestAnimationFrame(() => ball.classList.add('is-hit')); haptic(rally > 5 ? 'medium' : 'light'); if (rally >= 12) finish(true); else { nextBall(); clearTimeout(timer); timer = setTimeout(() => finish(false), Math.max(950 - rally * 35, 450)); } }
  function finish(success) { if (!running) return; running = false; clearTimeout(timer); const previous = shell().getStats(ID), result = shell().saveResult(ID, score, { bestRally: Math.max(previous.bestRally || 0, rally), lastResult: { score, rally, success } }), reward = Math.max(1, Math.floor(score / 130)); window.TelePlayCore?.RewardManager?.award(ID, { coins: reward, score, metadata: { transactionId: `game:${ID}:run:${Date.now()}`, rally, hits: rally } }); shell().emit('ping_pong_rush_finished', { gameId: ID, score, rally, reward, victory: success }); shell().emit('game_finished', { gameId: ID, score, reward, rally, victory: success }); shell().ResultScreen.show(screen.querySelector('[data-ping-result]'), { score, bestScore: result.bestScore, reward, newRecord: result.newRecord, title: success ? 'Матч<br>выигран!' : 'Ралли<br>прервано', details: { rally: `×${rally}`, hits: `${rally} / 12` } }); screen.querySelector('[data-ping-result]').hidden = false; }
  function start() { clearTimeout(timer); rally = 0; score = 0; running = true; paused = false; screen.querySelector('[data-ping-start]').hidden = true; screen.querySelector('[data-ping-result]').hidden = true; screen.querySelector('[data-ping-pause]').textContent = 'Ⅱ'; scoreEl.textContent = '0'; rallyEl.textContent = '×0'; shell().emit('ping_pong_rush_started', { gameId: ID }); shell().emit('game_started', { gameId: ID }); nextBall(); timer = setTimeout(() => finish(false), 1200); haptic('light'); }
  function open(options = {}) { callbacks = options; screen.hidden = false; screen.querySelector('[data-ping-start]').hidden = false; screen.querySelector('[data-ping-result]').hidden = true; const stats = shell().getStats(ID); screen.querySelector('[data-ping-menu-best]').textContent = Number(stats.bestScore || 0).toLocaleString('ru-RU'); try { tg?.requestFullscreen?.(); tg?.disableVerticalSwipes?.(); } catch (_) {} }
  function hide() { running = false; clearTimeout(timer); screen.hidden = true; try { tg?.enableVerticalSwipes?.(); tg?.exitFullscreen?.(); } catch (_) {} }
  function close() { hide(); callbacks.onHome?.(); }
  function pause() { if (!running) return; paused = !paused; screen.querySelector('[data-ping-pause]').textContent = paused ? '▶' : 'Ⅱ'; if (!paused) { timer = setTimeout(() => finish(false), 900); } else clearTimeout(timer); shell().emit(paused ? 'game_paused' : 'game_resumed', { gameId: ID }); }
  function init() { if (initialized) return; initialized = true; screen = $('pingPongScreen'); screen.innerHTML = `<div class="ping-pong-inner"><header class="ping-pong-hud"><button class="icon-button" data-ping-close aria-label="На главную">×</button><div class="ping-pong-brand"><small>TELEPLAY · СПОРТ</small><b>Ping Pong Rush</b></div><div class="ping-pong-stat"><small>РАЛЛИ</small><b data-ping-rally>×0</b></div><button class="icon-button" data-ping-pause aria-label="Пауза">Ⅱ</button></header><div class="ping-pong-court"><span class="ping-pong-net"></span><span class="ping-pong-paddle enemy"></span><span class="ping-pong-paddle player"></span><span class="ping-pong-ball" data-ping-ball></span></div><p class="ping-pong-hint" data-ping-hint>Следи за направлением мяча</p><div class="ping-pong-controls"><button type="button" data-ping-left aria-label="Ударить влево">‹ ВЛЕВО</button><button type="button" data-ping-right aria-label="Ударить вправо">ВПРАВО ›</button></div></div><div class="start-panel" data-ping-start><span class="panel-kicker">TELEPLAY · СПОРТ</span><h2>Ping Pong<br>Rush</h2><p>Возвращай мяч по траектории.<br>Наращивай серию ударов.</p><button class="play-button large" data-ping-start-button>Начать матч</button><div class="record">Лучший результат: <b data-ping-menu-best>0</b></div></div><div class="start-panel result-panel" data-ping-result hidden><span class="panel-kicker" data-result="kicker">МАТЧ ОКОНЧЕН</span><h2 data-result="title">Матч<br>выигран!</h2><div class="result-score"><small>РЕЗУЛЬТАТ</small><b data-result="score">0</b></div><div class="result-details"><span>Лучший результат <b data-result="best">0</b></span><span>Получено <b data-result="reward">+0 🪙</b></span><span>Ралли <b data-result="rally">×0</b></span><span>Удары <b data-result="hits">0 / 12</b></span></div><button class="play-button large" data-ping-replay>Новый матч</button><button class="text-button" data-ping-home>На главную</button></div>`; ball = screen.querySelector('[data-ping-ball]'); hint = screen.querySelector('[data-ping-hint]'); scoreEl = screen.querySelector('[data-ping-result]') ? screen.querySelector('[data-ping-result]').querySelector('[data-result="score"]') : null; rallyEl = screen.querySelector('[data-ping-rally]'); screen.querySelector('[data-ping-left]').addEventListener('click', () => hit('left')); screen.querySelector('[data-ping-right]').addEventListener('click', () => hit('right')); screen.querySelector('[data-ping-start-button]').addEventListener('click', start); screen.querySelector('[data-ping-replay]').addEventListener('click', start); screen.querySelector('[data-ping-home]').addEventListener('click', close); screen.querySelector('[data-ping-close]').addEventListener('click', close); screen.querySelector('[data-ping-pause]').addEventListener('click', pause); document.addEventListener('visibilitychange', () => { if (document.hidden && !screen.hidden && running && !paused) pause(); }); }
  window.PingPongRushGame = { init, open, hide, close, start, restart: start, pause, resume: () => { if (paused) pause(); }, destroy: hide };
  document.readyState === 'loading' ? document.addEventListener('DOMContentLoaded', init) : init();
})();
